        foreach (nint nativeItem in nativeItems)
        {
            if (nativeItem != 0 && Gst.GObject.Object.FromNative<Gst.PadTemplate>(nativeItem, Gst.Interop.Transfer.None) is { } adopted)
            {
                result.Add(adopted);
            }
        }

        return result;
    }

